import json

slug = (params.get("practice_slug") or "").strip()
problem = ""
settings = {}

def read_json(path):
    try:
        raw = api.files.read(file=path, scope="org")
    except Exception as exc:
        return None, "Couldn't read " + path + ": " + str(exc)
    try:
        return json.loads(raw), None
    except Exception as exc:
        return None, path + " isn't valid JSON (" + str(exc) + ")"

# No slug set (the param ships blank and can't be edited in the app): use
# the practice settings file, as long as there's exactly one.
if not slug:
    try:
        practice_entries = api.files.list(path="PracticeManager/Practices", scope="org") or []
    except Exception:
        practice_entries = []
    practice_slugs = []
    for e in practice_entries:
        name = str((e.get("name") if isinstance(e, dict) else e) or "").split("/")[-1]
        if name.endswith(".json"):
            practice_slugs.append(name[: -len(".json")])
    if len(practice_slugs) == 1:
        slug = practice_slugs[0]

if not slug:
    problem = "No practice_slug configured for this automation, and there isn't exactly one practice settings file in PracticeManager/Practices to fall back on."
else:
    found, err = read_json("PracticeManager/Practices/" + slug + ".json")
    if found is None:
        problem = err or ("No practice settings file found for slug '" + slug + "'.")
    else:
        settings = found

import json

slug = params["slug"]
prefix = slug + "-referral-followup-"

try:
    entries = api.files.list(path="PracticeManager/State", scope="org") or []
except Exception:
    entries = []

# Written by "Send approved referral request"; only the ones still waiting
# for a new referral are checked.
followups = []
for e in entries:
    name = str((e.get("name") if isinstance(e, dict) else e) or "").split("/")[-1]
    if not (name.startswith(prefix) and name.endswith(".json")):
        continue
    try:
        data = json.loads(api.files.read(file="PracticeManager/State/" + name, scope="org") or "{}") or {}
    except Exception:
        continue
    if isinstance(data, dict) and data.get("status") in ("waiting", "reminded"):
        data["_file_name"] = name
        followups.append(data)

import json
import datetime

def parse(iso_str):
    return datetime.datetime.fromisoformat(iso_str.replace("Z", "+00:00"))

def zulu(dt):
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

record = dict(params["followup"] or {})
file_name = str(record.pop("_file_name", "") or "")
todo_id = str(record.get("todo_id") or "")
patient_id = str(record.get("patient_id") or "")
patient_name = str(record.get("patient_name") or "")
case_id = str(record.get("case_id") or "")
old_expiry = str(record.get("expiry_date") or "")
old_max = record.get("max_sessions")
sent_at = str(record.get("sent_at") or "")
now = datetime.datetime.now(datetime.timezone.utc)

def comment(body):
    try:
        api.workq.comment(todo_id=todo_id, body=body)
    except Exception:
        pass

def referral_kind(c):
    rtype = str(c.get("referral_type") or "").lower()
    if rtype == "dva":
        return "DVA"
    if rtype == "medicare":
        return "Medicare"
    if not c.get("referral"):
        return ""
    name = str(c.get("name") or "").lower()
    if "dva" in name:
        return "DVA"
    if "medicare" in name:
        return "Medicare"
    return "Referral"

result = "waiting"

# Closed by hand already? Then stop watching.
item_status = ""
try:
    item_status = str((api.workq.get(todo_id=todo_id) or {}).get("status") or "")
except Exception:
    item_status = ""

if item_status in ("done", "cancelled"):
    result = "closed_by_hand"
    record["status"] = "closed"
else:
    # 1. Has a new referral arrived? Either a new Medicare/DVA case created
    # after the request, or this case extended (later expiry or more sessions).
    new_referral = None
    try:
        cases = api.connectors.invoke(server="cliniko-patients", tool="list_patient_cases",
                                      args={"patient_id": patient_id, "per_page": 100}) or {}
    except Exception:
        cases = {}
    for c in cases.get("patient_cases") or []:
        if c.get("archived_at") or not referral_kind(c):
            continue
        cid = str(c.get("id") or "")
        expiry = str(c.get("expiry_date") or "")
        max_s = c.get("max_sessions")
        if cid != case_id and str(c.get("created_at") or "") > sent_at:
            new_referral = c
            break
        if cid == case_id and ((expiry and expiry > old_expiry) or
                               (isinstance(max_s, int) and isinstance(old_max, int) and max_s > old_max)):
            new_referral = c
            break

    if new_referral is not None:
        result = "resolved"
        record["status"] = "resolved"
        record["resolved_at"] = zulu(now)
        comment("✅ New referral in Cliniko for " + patient_name + ": " + str(new_referral.get("name") or "case")
                + (", expires " + str(new_referral.get("expiry_date") or "") if new_referral.get("expiry_date") else "")
                + (", " + str(new_referral.get("max_sessions")) + " sessions" if new_referral.get("max_sessions") else "") + ".")
        try:
            api.workq.complete(todo_id=todo_id)
        except Exception:
            pass
    else:
        try:
            remind_at = parse(str(record.get("remind_at") or ""))
        except Exception:
            remind_at = now
        try:
            sent_dt = parse(sent_at)
        except Exception:
            sent_dt = now
        if record.get("status") == "waiting" and now >= remind_at:
            # 2. Not here yet: remind the manager once. Nothing is re-sent.
            result = "reminded"
            record["status"] = "reminded"
            record["reminded_at"] = zulu(now)
            comment("Reminder: no new referral has appeared in Cliniko for " + patient_name + " since the request went to the "
                    + ("GP" if record.get("sent_to") == "gp" else "patient") + " (" + str(record.get("recipient") or "") + ") on "
                    + sent_at[:10] + ". Please follow up with them.")
            try:
                api.workq.update(todo_id=todo_id, priority="high")
            except Exception:
                pass
        elif now - sent_dt > datetime.timedelta(days=30):
            # 3. Stop watching after a month; the item stays open for a human.
            result = "stopped"
            record["status"] = "stopped"
            comment("Stopped checking Cliniko for a new referral for " + patient_name + " (30 days since the request). Close this item once it's sorted.")

record["checked_at"] = zulu(now)
if file_name:
    api.files.put(file="PracticeManager/State/" + file_name, content=json.dumps(record, indent=2, sort_keys=True), scope="org")
